// Turns legal/*.md into src/legal.generated.ts so the app shows the exact published text.
// Run: npm run legal
const fs = require('fs');
const path = require('path');

const read = f => fs.readFileSync(path.join(__dirname, '..', 'legal', f), 'utf8').trim();
const out =
  '// GENERATED by scripts/gen-legal.js from legal/*.md. Do not edit.\n' +
  `export const PRIVACY_POLICY = ${JSON.stringify(read('PRIVACY_POLICY.md'))};\n` +
  `export const TERMS = ${JSON.stringify(read('TERMS.md'))};\n`;
fs.writeFileSync(path.join(__dirname, '..', 'src', 'legal.generated.ts'), out);
console.log('wrote src/legal.generated.ts');
